task_py = '''def transform(grid):
    n = len(grid)
    m = len(grid[0])
    count = sum(cell == 5 for row in grid for cell in row)
    zero_rows = [r for r in range(n) if sum(grid[r][c] == 0 for c in range(m)) > m // 2]
    zero_cols = [c for c in range(m) if sum(grid[r][c] == 0 for r in range(n)) > n // 2]
    out = [[7 for _ in range(m)] for _ in range(n)]
    cr, cc = n // 2, m // 2
    if len(zero_rows) == 2:
        paired_rows, fixed_cols = (cr - 1, cr + 1), zero_cols
        start = (m - count) // 2
        for r in paired_rows:
            out[r] = [0] * m
        for c in fixed_cols:
            for r in range(n):
                out[r][c] = 0
        for c in range(start, start + count):
            out[cr][c] = 5
    else:
        paired_cols, fixed_rows = (cc - 1, cc + 1), zero_rows
        start = (n - count) // 2
        for r in fixed_rows:
            out[r] = [0] * m
        for c in paired_cols:
            for r in range(n):
                out[r][c] = 0
        for r in range(start, start + count):
            out[r][cc] = 5
    return out
'''
